import { expect, test } from "bun:test";
import { formatDuration, parseDuration } from "./duration";

test("formats hours and minutes", () => {
  expect(formatDuration(5_400_000)).toBe("1h30m");
});

test("parses hours and minutes", () => {
  expect(parseDuration("1h30m")).toBe(5_400_000);
});

test("parses minutes only", () => {
  expect(parseDuration("45m")).toBe(2_700_000);
});

test("parses hours only", () => {
  expect(parseDuration("2h")).toBe(7_200_000);
});

test("parses zero minutes", () => {
  expect(parseDuration("0m")).toBe(0);
});

test("round-trips through formatDuration", () => {
  expect(parseDuration(formatDuration(5_400_000))).toBe(5_400_000);
  expect(parseDuration(formatDuration(2_700_000))).toBe(2_700_000);
});

test("throws on empty string", () => {
  expect(() => parseDuration("")).toThrow();
});

test("throws on garbage input", () => {
  expect(() => parseDuration("abc")).toThrow();
});

test("throws on missing unit", () => {
  expect(() => parseDuration("30")).toThrow();
});

test("throws on unsupported unit", () => {
  expect(() => parseDuration("30s")).toThrow();
});

test("throws on wrong order", () => {
  expect(() => parseDuration("30m1h")).toThrow();
});

test("throws on negative values", () => {
  expect(() => parseDuration("-5m")).toThrow();
});

test("throws on decimal values", () => {
  expect(() => parseDuration("1.5h")).toThrow();
});

test("throws on missing number before unit", () => {
  expect(() => parseDuration("h30m")).toThrow();
});

test("throws on trailing garbage", () => {
  expect(() => parseDuration("1h30mextra")).toThrow();
});

