const HOUR = 3_600_000;
const MINUTE = 60_000;

export function formatDuration(ms: number): string {
  const hours = Math.floor(ms / HOUR);
  const minutes = Math.floor((ms % HOUR) / MINUTE);
  return hours > 0 ? `${hours}h${minutes}m` : `${minutes}m`;
}

